-- =====================================================================
-- Mulheres & Quintais — Etapa 5: DADOS DE EXEMPLO (fictícios) para testar o sistema cheio
-- Gerado por supabase/exemplo/gerar.py. Rodar DEPOIS de 01 a 04.
--
-- O que entra: coordenação técnica, 10 bolsistas e 10 agentes de campo; 279 fichas nos 5 estados
-- (200 selecionadas e aprovadas); 800 visitas feitas e 200 diagnósticos com plano aprovado.
-- Nomes, CPFs e endereços são inventados. E-mails terminam em @exemplo.invalid (ninguém consegue entrar com eles).
--
-- Todo registro fica anotado na tabela public.exemplo: NÃO aparece na vitrine pública e sai inteiro com
-- 06_apagar_exemplo.sql. Rode o 06 ANTES de cadastrar a equipe e as fichas de verdade.
-- Por segurança, este script para se já houver equipe ou fichas reais no banco.
-- =====================================================================
begin;
-- >>> dados de exemplo (este bloco também vai no 05_dados_exemplo.sql)
-- Registros fictícios de teste ficam listados aqui: somem da vitrine pública e saem com 06_apagar_exemplo.sql
create table if not exists public.exemplo (
  tabela  text not null,
  id      uuid not null,
  primary key (tabela, id)
);
create index if not exists exemplo_id on public.exemplo (id);
alter table public.exemplo enable row level security;
drop policy if exists exemplo_ler on public.exemplo;
create policy exemplo_ler on public.exemplo for select to authenticated
  using (public.meu_papel() in ('coord_geral','coord_tecnico'));
grant select on public.exemplo to authenticated;

-- ninguém cria login com e-mail de pessoa de exemplo
create or replace function public.bloquear_conta_nao_cadastrada() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.equipe e where lower(e.email::text) = lower(new.email::text) and e.status = 'ativa'
                   and not exists (select 1 from public.exemplo x where x.id = e.id)) then
    raise exception 'E-mail não cadastrado no projeto.';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- Números públicos: só totais. Uma função, sem acesso às tabelas. Dados de exemplo não entram.
-- ---------------------------------------------------------------------
create or replace function public.vitrine() returns jsonb
language sql stable security definer set search_path = public as $$
  with ufs(uf) as (values ('AL'),('BA'),('PE'),('PI'),('SE')),
  ex as (select id from exemplo),
  sel as (select uf, count(*) n from fichas where resultado = 'selecionada' and situacao = 'aprovada' and id not in (select id from ex) group by uf),
  fic as (select uf, count(*) n from fichas where id not in (select id from ex) group by uf),
  dg  as (select uf, count(*) n, count(*) filter (where situacao = 'aprovado') aprov from diagnosticos where id not in (select id from ex) group by uf),
  imp as (select uf, count(*) n from visitas where etapa = 'implantacao' and situacao = 'realizada' and id not in (select id from ex) group by uf),
  aco as (select uf, count(*) n from visitas where etapa = 'acompanhamento' and situacao = 'realizada' and id not in (select id from ex) group by uf),
  eq  as (select count(*) filter (where papel in ('articulacao','apoio')) bolsistas,
                 count(*) filter (where papel = 'agente') agentes
            from equipe where status = 'ativa' and id not in (select id from ex)),
  por_uf as (
    select jsonb_agg(jsonb_build_object(
             'uf', u.uf,
             'fichas', coalesce(fic.n, 0),
             'selecionadas', coalesce(sel.n, 0),
             'diagnosticos', coalesce(dg.n, 0),
             'planos', coalesce(dg.aprov, 0),
             'implantados', coalesce(imp.n, 0),
             'acompanhamentos', coalesce(aco.n, 0)) order by u.uf) j
      from ufs u
      left join sel on sel.uf = u.uf left join fic on fic.uf = u.uf left join dg on dg.uf = u.uf
      left join imp on imp.uf = u.uf left join aco on aco.uf = u.uf),
  fotos as (
    select coalesce(jsonb_agg(jsonb_build_object('path', v.path, 'legenda', v.legenda, 'uf', v.uf)
                              order by v.publicada_em desc), '[]'::jsonb) j
      from (select vf.* from vitrine_fotos vf join fichas f on f.id = vf.ficha_id
             where f.consent_imagem and (f.consent_criancas or vf.sem_criancas) and f.id not in (select id from ex)
             order by vf.publicada_em desc limit 24) v)
  select jsonb_build_object(
    'atualizado_em', now(),
    'por_uf', (select j from por_uf),
    'equipe', (select to_jsonb(eq) from eq),
    'fotos', (select j from fotos));
$$;

do $$ begin
  if exists (select 1 from public.equipe where papel <> 'coord_geral' and id not in (select id from public.exemplo)) then
    raise exception 'Já há equipe cadastrada de verdade: os dados de exemplo não foram colocados (nada mudou).';
  end if;
  if exists (select 1 from public.fichas where id not in (select id from public.exemplo)) then
    raise exception 'Já há fichas de verdade: os dados de exemplo não foram colocados (nada mudou).';
  end if;
  if exists (select 1 from public.exemplo) then
    raise exception 'Os dados de exemplo já estão no banco. Para recolocar, rode antes o 06_apagar_exemplo.sql.';
  end if;
end $$;

-- as regras do sistema (gatilhos) ficam desligadas só durante a carga, para gravar datas e aprovações de uma vez
alter table public.equipe disable trigger user;
alter table public.fichas disable trigger user;
alter table public.visitas disable trigger user;
alter table public.diagnosticos disable trigger user;


alter table public.equipe enable trigger user;
alter table public.fichas enable trigger user;
alter table public.visitas enable trigger user;
alter table public.diagnosticos enable trigger user;
commit;

select 'Dados de exemplo colocados' as resultado,
  (select count(*) from public.exemplo where tabela = 'equipe') as equipe,
  (select count(*) from public.exemplo where tabela = 'fichas') as fichas,
  (select count(*) from public.exemplo where tabela = 'visitas') as visitas,
  (select count(*) from public.exemplo where tabela = 'diagnosticos') as diagnosticos;

